/// <summary>
/// Extended stand method to update AMEX journal number.
/// </summary>
/// <returns>LedgerJournalId</returns>
public LedgerJournalId transferToNewLedgerTable()
{
    JournalId    metNewJournal = next transferToNewLedgerTable();
    
    //MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
    LedgerJournalTable  metNewJournalTable = LedgerJournalTable::find(metNewJournal, false);
    if (metNewJournalTable
            && metNewJournalTable.JournalName == CustParameters::find().METAMEXJournalName)
    {
        if(!CustParameters::find().METAMEXIsAdhocJournal)
        {
            CustParameters::METUpdateAMEXJournalNum(metNewJournal);
            if (metNewJournalTable.OriginalJournalNum)
            {
                CustParameters::METUpdateAMEXFreeTextInvJournalNum(metNewJournalTable.OriginalJournalNum);
            }
        }
        else
        {
            // MPJ-19186 - Update FTI flag for Adhoc journals 
            LedgerJournalTable  metOrigJournalTable = LedgerJournalTable::find(metNewJournalTable.OriginalJournalNum, true);
            if (metOrigJournalTable)
            {
                ttsbegin;
                metOrigJournalTable.METAMEXProcessFTI = NoYes::Yes;
                metOrigJournalTable.doUpdate();
                ttscommit;
            }
        }
    }
    return metNewJournal;
}

    /// <summary>
    /// MET_122589_RPAGeneralLedgerIntegration developed by yadavpa on 25/03/2024
    /// RPA Ledger Integration
    /// </summary>
    /// <param name = "_journalTable"></param>
    protected void updateTableInfoLog(LedgerJournalTable _journalTable)
    {
        LedgerJournalTable  ledgerJournalTableErrorCapture;
        boolean             flag = true;

        next  updateTableInfoLog(_journalTable);
        if(flag)
        {
            select forupdate ledgerJournalTableErrorCapture where
                ledgerJournalTableErrorCapture.RecId == _journalTable.RecId ;
            if(ledgerJournalTableErrorCapture.RecId)
            {
                ttsbegin;
                ledgerJournalTableErrorCapture.METErrorLog = tableErrorLog;
                ledgerJournalTableErrorCapture.update();
                ttscommit;

                flag = false;
            }
        }
    }
